{
public:
	const Overridable *getFinalOverride() const;

	void *m_vptr;
	const Overridable *m_nextOverride;
};

class ThingTemplate : public Overridable
{
public:
	unsigned char m_pad08[0x444 - 8];
	Int m_bfme444;
	unsigned char m_pad448[0x4cc - 0x448];
	Bool m_bfme4CC;
};

class BfmeAIView204
{
public:
	unsigned char m_pad[0x1b8];
