};

class Object
{
public:
	Bool bfmeIsComputerControlled() const;
	Int getLayer() const;
	const ThingTemplate *getTemplate() const
	{
		const ThingTemplate *d = m_template;
		if (d == 0)
			return d;
		return (const ThingTemplate *)(d->m_nextOverride ? d->m_nextOverride->getFinalOverride() : d);
	}
	const Coord3D *getPosition() const { return &m_pos; }
	BfmeAIView204 *getAI() const { return m_bfme204; }

	void *m_vptr;
	const ThingTemplate *m_template;
	unsigned char m_pad08[0x38 - 8];
	Coord3D m_pos;
	unsigned char m_pad44[0x204 - 0x44];
	BfmeAIView204 *m_bfme204;
};

class TerrainLogic
{
public:
	PathfindLayerEnum getLayerForDestination(Object *obj, const Coord3D *pos);
};
extern TerrainLogic *TheTerrainLogic;

class BfmeStepInfo
{
public:
	Int m_surfaces;
	Bool m_field04;
	Bool m_allowAircraftGoal;
	char m_pad06[2];
	Int m_maxLayer;
};

class Path
{
public:
	Path();

	unsigned char m_pad00[0x0c];
	Bool m_complete;
	unsigned char m_pad0d[0x24 - 0x0d];
};

class Pathfinder
{
public:
	Path *getAircraftPath(const Object *obj, const Coord3D *to);
	Bool bfmeStepD4F90(void *movementInfo, PathfindCell *pathfindCell);
	Bool worldToCell(const Coord3D *pos, ICoord2D *cell);
	PathfindCell *getCell(PathfindLayerEnum layer, Int x, Int y);
	PathfindCell *getClippedCell(PathfindLayerEnum layer, const Coord3D *pos);
	UnsignedInt rva003DB900(PathfindCell *cell, PathfindCell *goalCell);
	void rva003D6400(PathfindCell *cell);
	PathfindCell *rva003D6490();
	void rva003DAE40(PathfindCell *cell, Object *obj);
	void rva003D5FC0();
	void prependCells(Path *path, const Coord3D *fromPos, PathfindCell *goalCell, Bool center);

protected:
	void getRadiusAndCenter(const Object *obj, Int &radius, Bool &center);

private:
	unsigned char m_opaque00[0x838];
	PathfindCellInfo *m_closedList;		// +0x838
	Bool m_isTunneling;					// +0x83C
	unsigned char m_pad83d[0x844 - 0x83d];
	Int m_ignoreObstacleID;				// +0x844
};

Path *Pathfinder::getAircraftPath(const Object *obj, const Coord3D *to)
{
	m_ignoreObstacleID = 0;
	Bool center;
	{
		Int radius;
		getRadiusAndCenter(obj, radius, center);
	}
	const Coord3D *from = obj->getPosition();
	PathfindCell *goalCell;
	BfmeStepInfo stepInfo;
	Int cellCount;
	{
		Coord3D start = *from;
		Coord3D destination = *to;
		if (!center)
		{
			start.x += PATHFIND_CELL_SIZE_F/2;
			start.y += PATHFIND_CELL_SIZE_F/2;
			destination.x += PATHFIND_CELL_SIZE_F/2;
			destination.y += PATHFIND_CELL_SIZE_F/2;
		}

		ICoord2D startCellNdx;
		ICoord2D goalCellNdx;
		worldToCell(&start, &startCellNdx);
		worldToCell(&destination, &goalCellNdx);
		if (startCellNdx.x == goalCellNdx.x && startCellNdx.y == goalCellNdx.y)
			return 0;

		Int templateLayer = obj->getTemplate()->m_bfme444;
		Bool templateFlag = obj->getTemplate()->m_bfme4CC;
		BfmeAIView204 *ai = obj->getAI();
		Bool isComputer = obj->bfmeIsComputerControlled();
		stepInfo.m_surfaces = ai->m_bfme1B8;
		stepInfo.m_field04 = !templateFlag;
		stepInfo.m_allowAircraftGoal = isComputer;
		PathfindLayerEnum destinationLayer = TheTerrainLogic->getLayerForDestination((Object *)obj, to);
		stepInfo.m_maxLayer = templateLayer - 1;

		ICoord2D cell;
		if (worldToCell(&destination, &cell))
			return 0;
		goalCell = getCell(destinationLayer, cell.x, cell.y);
		if (goalCell == 0)
			return 0;
		if (!bfmeStepD4F90(&stepInfo, goalCell))
			return 0;
		PathfindCell *parentCell = getClippedCell((PathfindLayerEnum)obj->getLayer(), &start);
		if (parentCell == 0)
			return 0;

		goalCell->allocateInfo(&goalCellNdx);
		parentCell->allocateInfo(&startCellNdx);
		parentCell->startPathfind(goalCell);
		parentCell->m_info->m_totalCost = (UnsignedShort)rva003DB900(parentCell, goalCell);
		rva003D6400(parentCell);
	}

	cellCount = 0;
	{
		PathfindCell *parentCell;
		while ((parentCell = rva003D6490()) != 0)
		{
			if (parentCell == goalCell)
			{
				Path *path = new Path;
				prependCells(path, from, goalCell, center);
				path->m_complete = true;
				goalCell->rva003F6F10();
				rva003D5FC0();
				return path;
			}

			parentCell->rva003F6C30(&m_closedList);
			if (cellCount > 200)
				break;

			rva003DAE40(parentCell, (Object *)obj);

			static Int deltaX[] = { 1, 0, -1, 0, 1, -1, -1, 1 };
			static Int deltaY[] = { 0, 1, 0, -1, 1, 1, -1, -1 };
			const Int numNeighbors = 8;
			const Int firstDiagonal = 4;
			ICoord2D newCellCoord;
			PathfindCell *newCell;
			const Int adjacent[5] = { 0, 1, 2, 3, 0 };
			Bool neighborFlags[8];

			for (Int i = 0; i < numNeighbors; i++)
			{
				neighborFlags[i] = false;
				newCellCoord.x = parentCell->getXIndex() + deltaX[i];
				newCellCoord.y = parentCell->getYIndex() + deltaY[i];

				newCell = getCell(parentCell->getLayer(), newCellCoord.x, newCellCoord.y);
				if (newCell == 0)
					continue;

				if (newCell->getClosed() || newCell->getOpen())
					continue;

				Int newLayer = newCell->getLayer();
				if (newLayer != parentCell->getLayer() &&
					newLayer != parentCell->getConnectLayer() &&
					newCell->getConnectLayer() != parentCell->getLayer() &&
					(parentCell->getConnectLayer() != 0x10 ||
					 newCell->getConnectLayer() != parentCell->getConnectLayer()))
					continue;

				if (i >= firstDiagonal)
				{
					if (!neighborFlags[adjacent[i - 4]] && !neighborFlags[adjacent[i - 3]])
						continue;
				}

				if (!bfmeStepD4F90(&stepInfo, newCell))
				{
					newCell->allocateInfo(&newCellCoord);
					newCell->rva003F6C30(&m_closedList);
					continue;
				}

				neighborFlags[i] = true;
				if (!newCell->hasInfo())
					cellCount++;
				newCell->allocateInfo(&newCellCoord);

				UnsignedInt newCostSoFar = newCell->costSoFar(parentCell);
				Int dx = newCellCoord.x - goalCell->getXIndex();
				if (dx < 0) dx = -dx;
				Int dy = newCellCoord.y - goalCell->getYIndex();
				if (dy < 0) dy = -dy;
				if (newCell->getBit18() && dx + dy > 3)
					newCostSoFar += 10;
				newCell->m_info->m_flags &= ~1u;
				UnsignedInt costRemaining = rva003DB900(newCell, goalCell);
				if (newCell->getType() == 4)
					newCostSoFar += 1000;
				newCell->m_info->m_costSoFar = (UnsignedShort)newCostSoFar;
				newCell->setParentCell(parentCell);
				newCell->m_info->m_totalCost = newCell->m_info->m_costSoFar + costRemaining;
				rva003D6400(newCell);
			}
		}
	}

	rva003D5FC0();
	goalCell->rva003F6F10();
	return 0;
}

